import { useEffect, useMemo, useState } from "react";
import {
  Bell,
  Bot,
  CircleUserRound,
  Compass,
  Diamond,
  FileText,
  GitPullRequest,
  Mic,
  Paperclip,
  Search,
  SendHorizontal,
  Server,
  Settings,
  Shield,
  Sparkles,
  Ticket,
  Workflow
} from "lucide-react";
import { checkHealth, sendPrompt } from "./api";

const sidebarSections = [
  {
    title: "Services",
    items: [
      { icon: Workflow, label: "EMH Hub", active: true },
      { icon: Server, label: "Kafka Connectors" },
      { icon: Search, label: "AKHQ" },
      { icon: Shield, label: "Schema Registry" }
    ]
  },
  {
    title: "Operations",
    items: [
      { icon: CircleUserRound, label: "ServiceNow ITOM" },
      { icon: Diamond, label: "Jira Software" },
      { icon: GitPullRequest, label: "GitLab" },
      { icon: Sparkles, label: "JFrog Artifactory" }
    ]
  },
  {
    title: "Docs",
    items: [
      { icon: FileText, label: "Application Docs" },
      { icon: Compass, label: "Tutorials" }
    ]
  }
];

const starterMessages = [
  {
    id: "welcome-1",
    role: "assistant",
    text: "Ask about Kafka, ServiceNow, Jira, PRs, and code changes."
  }
];

function App() {
  const [prompt, setPrompt] = useState("");
  const [mode, setMode] = useState("chat");
  const [sessionId, setSessionId] = useState("");
  const [messages, setMessages] = useState(starterMessages);
  const [isLoading, setIsLoading] = useState(false);
  const [healthStatus, setHealthStatus] = useState("checking");
  const [error, setError] = useState("");

  useEffect(() => {
    let cancelled = false;

    async function loadHealth() {
      try {
        await checkHealth();
        if (!cancelled) {
          setHealthStatus("online");
        }
      } catch {
        if (!cancelled) {
          setHealthStatus("offline");
        }
      }
    }

    loadHealth();
    return () => {
      cancelled = true;
    };
  }, []);

  const modeDescription = useMemo(() => {
    if (mode === "agent") {
      return "Agent mode uses MCP tools for actions across Jira, Git, JFrog, and more.";
    }
    return "Chat mode answers directly without MCP tools to reduce token and tool usage.";
  }, [mode]);

  async function onSubmit(event) {
    event.preventDefault();
    const trimmedPrompt = prompt.trim();
    if (!trimmedPrompt || isLoading) {
      return;
    }

    setError("");
    setIsLoading(true);

    const userMessage = {
      id: `u-${Date.now()}`,
      role: "user",
      text: trimmedPrompt
    };

    setMessages((current) => [...current, userMessage]);
    setPrompt("");

    try {
      const result = await sendPrompt({
        prompt: trimmedPrompt,
        mode,
        sessionId
      });

      if (result?.sessionId) {
        setSessionId(result.sessionId);
      }

      const responseText = result?.response || "No response received.";
      const toolsUsed = Array.isArray(result?.toolsUsed) ? result.toolsUsed : [];
      const toolInfo = mode === "agent" && toolsUsed.length > 0
        ? `\n\nTools used: ${toolsUsed.join(", ")}`
        : "";

      setMessages((current) => [
        ...current,
        {
          id: `a-${Date.now()}`,
          role: "assistant",
          text: `${responseText}${toolInfo}`
        }
      ]);
    } catch (submitError) {
      const errorMessage = submitError instanceof Error ? submitError.message : "Request failed";
      setError(errorMessage);
      setMessages((current) => [
        ...current,
        {
          id: `e-${Date.now()}`,
          role: "assistant",
          text: `Error: ${errorMessage}`
        }
      ]);
    } finally {
      setIsLoading(false);
    }
  }

  return (
    <div className="app-shell">
      <aside className="left-sidebar">
        <div className="brand-row">
          <Sparkles size={20} />
          <span>EMH INTEGRATION HUB</span>
        </div>

        {sidebarSections.map((section) => (
          <div key={section.title} className="sidebar-section">
            <div className="section-title">{section.title}</div>
            {section.items.map((item) => (
              <button key={item.label} className={`nav-item ${item.active ? "active" : ""}`}>
                <item.icon size={18} />
                <span>{item.label}</span>
              </button>
            ))}
          </div>
        ))}
      </aside>

      <main className="main-layout">
        <header className="top-bar">
          <div className="search-box">
            <Search size={16} />
            <input
              type="text"
              placeholder="Search topics, connectors, tickets, services..."
              readOnly
            />
          </div>

          <div className="top-actions">
            <Bell size={18} />
            <div className="profile">
              <CircleUserRound size={24} />
              <div>
                <div className="profile-name">Integration Engineer</div>
                <div className="profile-status">
                  <span className={`dot ${healthStatus}`} />
                  {healthStatus === "online" ? "Online" : healthStatus === "offline" ? "Offline" : "Checking"}
                </div>
              </div>
            </div>
          </div>
        </header>

        <div className="content-grid">
          <section className="chat-panel">
            <div className="chat-header">
              <div>
                <h2>ASK EMH AI AGENT</h2>
                <p>Ask about Kafka, ServiceNow, Jira, PRs, code changes...</p>
              </div>
              <div className="mode-picker">
                <label htmlFor="modeSelect">Mode</label>
                <select
                  id="modeSelect"
                  value={mode}
                  onChange={(event) => setMode(event.target.value)}
                >
                  <option value="chat">Chat</option>
                  <option value="agent">Agent</option>
                </select>
              </div>
            </div>

            <div className="mode-banner">{modeDescription}</div>

            <div className="messages-area">
              {messages.map((message) => (
                <div key={message.id} className={`message-row ${message.role}`}>
                  <div className="avatar">
                    {message.role === "assistant" ? <Bot size={18} /> : <CircleUserRound size={18} />}
                  </div>
                  <div className="bubble">{message.text}</div>
                </div>
              ))}
              {isLoading && (
                <div className="message-row assistant">
                  <div className="avatar"><Bot size={18} /></div>
                  <div className="bubble">Thinking...</div>
                </div>
              )}
            </div>

            <form className="composer" onSubmit={onSubmit}>
              <input
                value={prompt}
                onChange={(event) => setPrompt(event.target.value)}
                placeholder="Ask about Kafka, ServiceNow, Jira, PRs, code changes..."
              />
              <button type="button" className="icon-btn" aria-label="voice input">
                <Mic size={18} />
              </button>
              <button type="button" className="icon-btn" aria-label="attach file">
                <Paperclip size={18} />
              </button>
              <button type="submit" className="send-btn" disabled={isLoading || !prompt.trim()}>
                <SendHorizontal size={18} />
              </button>
            </form>

            {error && <div className="error-banner">{error}</div>}
          </section>

          <aside className="context-panel">
            <h3>CURRENT SYSTEM CONTEXT</h3>
            <p>Dynamic information linked to the chat</p>

            <div className="context-card">
              <div className="card-title"><Ticket size={16} /> Jira Ticket [EMH-401]</div>
              <div>Status: Open</div>
              <div>Topic: order_processed</div>
              <div>Lag: High</div>
              <div>Assigned: Me</div>
            </div>

            <div className="context-card">
              <div className="card-title"><Server size={16} /> Kafka Connector</div>
              <div>order-processing-connector</div>
              <div>Status: Running</div>
              <div>Partition Lag: 125,123</div>
            </div>

            <div className="context-card">
              <div className="card-title"><GitPullRequest size={16} /> GitLab PR #115</div>
              <div>Status: Open</div>
            </div>

            <div className="context-card">
              <div className="card-title"><Sparkles size={16} /> JFrog Artifact</div>
              <div>payment-service v1.4.2</div>
              <div>Status: Published</div>
            </div>

            <div className="session-id">Session: {sessionId || "new session"}</div>
          </aside>
        </div>
      </main>
    </div>
  );
}

export default App;
